'use strict';
// V21: behavior-preserving extraction; compatibility globals remain in phase 1.
function stop(){document.querySelectorAll('.story-layer').forEach(n=>n.classList.remove('beat-inspect'));clearTimeout(timer);if(storyRuntime)storyRuntime.reset();$('canvas').classList.remove('active');}
function animate(){if(!generatedStory){notice('Select a style and apply the animation first.');return;}if(previewVersion==='original'){previewVersion='story';render();}if(storyRuntime){if(!settings().layers.length){notice('Choose Individual objects in Animation Settings and select an object.');return;}storyRuntime.play();}}
function motionCss(s){const lift=s.strength*1.5,scale=1+s.strength*.004;return `.figure svg{display:block;width:100%;height:auto}.figure .motion-layer{transform-box:fill-box;transform-origin:center}.figure.active[data-effect=lift] .motion-layer{animation:studioLift ${s.duration}ms cubic-bezier(.2,.7,.2,1) both}.figure.active[data-effect=pulse] .motion-layer{animation:studioPulse ${s.duration}ms ease-in-out both}.figure.active[data-effect=reveal] .motion-layer{animation:studioReveal ${s.duration}ms ease both;animation-delay:var(--delay)}.figure.active[data-effect=flow] .motion-layer{animation:studioFlow ${s.duration}ms ease both;animation-delay:var(--delay)}@keyframes studioLift{0%,100%{transform:translateY(0)}45%{transform:translateY(-${lift}px)}}@keyframes studioPulse{0%,100%{transform:scale(1);filter:brightness(1)}50%{transform:scale(${scale});filter:brightness(1.35)}}@keyframes studioReveal{0%{opacity:.3;transform:translateY(${lift}px)}70%,100%{opacity:1;transform:translateY(0)}}@keyframes studioFlow{0%,100%{opacity:1;filter:brightness(1)}40%{opacity:.55;filter:brightness(1.7)}}@media(prefers-reduced-motion:reduce){.figure.active .motion-layer{animation:none!important}}`;}
